//! Person identity (P2; cutex-desktop docs/research/person-identity-p2-20261014.md).
//!
//! A *person* is an Ed25519 key pair generated by a desktop. Weak
//! authentication: a key only answers "who is this", so a paired device can
//! land on the right local user automatically and the same person is
//! recognised on several hosts. Admission still needs pairing (a token); a
//! key never grants anything by itself, and a presented key must come with a
//! signature over a one-use host challenge.
//!
//! - Store: `<cutex home>/runtime/users/persons-v1.json`, schema
//!   `cutex/persons/v1`, written under the users store's `users.lock` with
//!   the same atomic writer. `users-v1.json` keeps its P1 format (an older
//!   cutex refuses any other schema there); without this file there is no
//!   person identity and behaviour is exactly P1's.
//! - `users`: userId → person keys (a key belongs to at most one user).
//!   `tokenPersons`: tokenId → the key the device presented (display only;
//!   the token → user binding stays in `users-v1.json`). `tokenClaims`: when,
//!   the self-set name a pending device sent, and the previous key when a
//!   device later presented another one. `peerPersons`: peerId → the remote
//!   owner's keys sent at peer pairing. `ownerPerson` (capability
//!   `host-owner-person`, cutex-desktop
//!   docs/research/host-ownership-20261019.md §1): which owner key is the
//!   host owner *in person*; see [`OwnerPerson`] and [`effective_owner_person`].
//! - Fields this build does not know are kept on rewrite (`extra`), so a
//!   later field survives a rollback to this build.
//! - Challenges live in memory only: one use, [`CHALLENGE_TTL`], at most
//!   [`MAX_CHALLENGES`] outstanding ([`MAX_CHALLENGES_PER_CALLER`] per caller).
//! - Public keys are stored and shown as base64url without padding of the raw
//!   32 bytes (the JWK `x` of an OKP Ed25519 key); `fingerprint` = the first
//!   16 hex digits of SHA-256 of those 32 bytes.

use std::collections::{BTreeMap, HashSet};
use std::path::{Path, PathBuf};
use std::sync::Mutex;
use std::time::{Duration, Instant};

use base64::Engine;
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use sha2::{Digest, Sha256};

use crate::management::users::{self, audit, UserError, UserStore, OWNER};

pub const SCHEMA: &str = "cutex/persons/v1";
pub const SIGNING_PREFIX: &str = "cutex-identity-v1";
/// The `tokenId` a root-credential caller signs (it has no client token).
pub const ROOT_TOKEN_ID: &str = "root";
pub const CHALLENGE_TTL: Duration = Duration::from_secs(30);
pub const MAX_CHALLENGES: usize = 256;
pub const MAX_CHALLENGES_PER_CALLER: usize = 4;
pub const MAX_KEYS_PER_USER: usize = 16;
pub const MAX_PEER_KEYS: usize = 8;
const MAX_LABEL_CHARS: usize = 60;

// ---------------------------------------------------------------- model

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PersonKey {
    pub public_key: String,
    pub added_at: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub label: Option<String>,
}

impl PersonKey {
    pub fn view(&self) -> Value {
        json!({
            "publicKey": self.public_key,
            "fingerprint": fingerprint(&self.public_key),
            "addedAt": self.added_at,
            "label": self.label,
        })
    }
}

#[derive(Clone, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TokenClaim {
    pub claimed_at: String,
    /// Self-set name a device sent with its claim (shown on the pending card).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub display_name: Option<String>,
    /// Set when an already-recorded device presented a different key.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub previous_public_key: Option<String>,
}

/// Sources of [`OwnerPerson`] with a key: the first key added to owner by a
/// root-credential claim, by the host's first paired device, set locally
/// (CLI / root credential on loopback), or inferred from the audit log /
/// the only owner key when the field was first written.
pub const OWNER_PERSON_SOURCES: &[&str] = &["firstRootClaim", "firstPairing", "local", "audit"];
/// Sources of an explicitly unconfirmed [`OwnerPerson`] (`publicKey` null):
/// cleared locally, its key removed from owner, or not determinable when the
/// owner keys first changed after an upgrade.
pub const OWNER_PERSON_UNSET_SOURCES: &[&str] = &["local", "keyRemoved", "undetermined"];

/// `ownerPerson` in persons-v1.json: absent = never decided (inferred on
/// read, see [`effective_owner_person`]); `publicKey` null = explicitly
/// unconfirmed (no inference; only a local set confirms it again).
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct OwnerPerson {
    #[serde(default)]
    pub public_key: Option<String>,
    #[serde(default)]
    pub set_at: String,
    #[serde(default)]
    pub source: String,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct State {
    pub schema: String,
    #[serde(default)]
    pub revision: u64,
    /// userId → keys.
    #[serde(default)]
    pub users: BTreeMap<String, Vec<PersonKey>>,
    /// tokenId → presented key.
    #[serde(default)]
    pub token_persons: BTreeMap<String, String>,
    #[serde(default)]
    pub token_claims: BTreeMap<String, TokenClaim>,
    /// peerId → the remote owner's keys (sent at peer pairing).
    #[serde(default)]
    pub peer_persons: BTreeMap<String, Vec<String>>,
    /// The owner in person (host-owner-person); absent on older files.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub owner_person: Option<OwnerPerson>,
    /// Unknown top-level fields, written back unchanged.
    #[serde(flatten)]
    pub extra: serde_json::Map<String, Value>,
}

impl Default for State {
    fn default() -> Self {
        Self {
            schema: SCHEMA.into(),
            revision: 0,
            users: BTreeMap::new(),
            token_persons: BTreeMap::new(),
            token_claims: BTreeMap::new(),
            peer_persons: BTreeMap::new(),
            owner_person: None,
            extra: serde_json::Map::new(),
        }
    }
}

impl State {
    /// The user a key belongs to (only users that still exist).
    pub fn user_of_key(&self, users: &users::State, key: &str) -> Option<String> {
        self.users
            .iter()
            .find(|(user, keys)| users.user(user).is_some() && keys.iter().any(|k| k.public_key == key))
            .map(|(user, _)| user.clone())
    }

    pub fn keys_of(&self, user: &str) -> &[PersonKey] {
        self.users.get(user).map(Vec::as_slice).unwrap_or_default()
    }

    fn add_key(&mut self, user: &str, key: &str, now: &str) {
        let keys = self.users.entry(user.to_string()).or_default();
        if !keys.iter().any(|k| k.public_key == key) {
            keys.push(PersonKey { public_key: key.to_string(), added_at: now.to_string(), label: None });
        }
    }

    /// Add a claimed key to owner. The first key ever added to an owner
    /// without an `ownerPerson` becomes the owner person (`source`); a file
    /// written before host-owner-person first settles its inferred owner
    /// person, so a later claim never takes over.
    fn add_owner_key(&mut self, key: &str, source: &str, audit_dir: &Path) {
        self.settle_owner_person(audit_dir);
        let first = self.owner_person.is_none() && self.keys_of(OWNER).is_empty();
        let now = crate::management::instance::now_utc();
        self.add_key(OWNER, key, &now);
        if first {
            self.owner_person = Some(OwnerPerson { public_key: Some(key.to_string()), set_at: now, source: source.into() });
        }
    }

    /// Before owner's keys change: a file without `ownerPerson` but with
    /// owner keys gets its inferred owner person written down (source
    /// `audit`), or an explicit unconfirmed marker (`undetermined`), so the
    /// change cannot shift the inference.
    fn settle_owner_person(&mut self, audit_dir: &Path) {
        if self.owner_person.is_some() || self.keys_of(OWNER).is_empty() {
            return;
        }
        let now = crate::management::instance::now_utc();
        self.owner_person = Some(match infer_owner_person(self, audit_dir) {
            Some(key) => OwnerPerson { public_key: Some(key), set_at: now, source: "audit".into() },
            None => OwnerPerson { public_key: None, set_at: now, source: "undetermined".into() },
        });
    }

    /// The owner person's key is no longer one of owner's keys: unconfirmed.
    fn drop_removed_owner_person(&mut self) {
        let removed = self
            .owner_person
            .as_ref()
            .and_then(|person| person.public_key.as_deref())
            .is_some_and(|key| !self.keys_of(OWNER).iter().any(|k| k.public_key == key));
        if removed {
            self.owner_person = Some(OwnerPerson {
                public_key: None,
                set_at: crate::management::instance::now_utc(),
                source: "keyRemoved".into(),
            });
        }
    }

    fn check(&self) -> anyhow::Result<()> {
        if self.schema != SCHEMA {
            anyhow::bail!("unsupported persons store schema");
        }
        let mut seen = HashSet::new();
        for keys in self.users.values() {
            for key in keys {
                if !seen.insert(key.public_key.as_str()) {
                    anyhow::bail!("a person key belongs to more than one user");
                }
            }
        }
        Ok(())
    }
}

// ---------------------------------------------------------------- keys

fn decode_b64(text: &str) -> Option<Vec<u8>> {
    use base64::engine::general_purpose::{STANDARD, STANDARD_NO_PAD, URL_SAFE, URL_SAFE_NO_PAD};
    let text = text.trim();
    [URL_SAFE_NO_PAD, URL_SAFE, STANDARD_NO_PAD, STANDARD]
        .iter()
        .find_map(|engine| engine.decode(text).ok())
}

fn encode_b64(bytes: &[u8]) -> String {
    base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(bytes)
}

/// Canonical form (base64url, no padding) of an Ed25519 public key given as
/// base64 / base64url of its raw 32 bytes.
pub fn normalize_public_key(text: &str) -> Option<String> {
    if text.len() > 64 {
        return None;
    }
    decode_b64(text).filter(|bytes| bytes.len() == 32).map(|bytes| encode_b64(&bytes))
}

pub fn fingerprint(public_key: &str) -> String {
    let bytes = decode_b64(public_key).unwrap_or_default();
    Sha256::digest(&bytes).iter().take(8).map(|b| format!("{b:02x}")).collect()
}

/// The exact bytes a claim signs.
pub fn signing_message(host_id: &str, nonce: &str, token_id: &str) -> String {
    format!("{SIGNING_PREFIX}\n{host_id}\n{nonce}\n{token_id}")
}

pub fn verify_signature(public_key: &str, message: &[u8], signature: &str) -> bool {
    let (Some(key), Some(signature)) = (decode_b64(public_key), decode_b64(signature).filter(|s| s.len() == 64))
    else {
        return false;
    };
    ring::signature::UnparsedPublicKey::new(&ring::signature::ED25519, key)
        .verify(message, &signature)
        .is_ok()
}

// ---------------------------------------------------------------- challenges

struct Challenge {
    nonce: String,
    caller: String,
    expires: Instant,
}

pub struct Challenges {
    inner: Mutex<Vec<Challenge>>,
}

#[derive(Debug, PartialEq, Eq)]
pub enum ChallengeError {
    TooMany,
    Unavailable,
}

impl Challenges {
    pub const fn new() -> Self {
        Self { inner: Mutex::new(Vec::new()) }
    }

    pub fn global() -> &'static Self {
        static GLOBAL: Challenges = Challenges::new();
        &GLOBAL
    }

    /// A fresh nonce for `caller` (tokenId or [`ROOT_TOKEN_ID`]). A caller
    /// keeps at most [`MAX_CHALLENGES_PER_CALLER`] (its oldest is dropped);
    /// the host at most [`MAX_CHALLENGES`] (then refused until some expire).
    pub fn issue(&self, caller: &str, now: Instant) -> Result<String, ChallengeError> {
        let mut bytes = [0u8; 32];
        ring::rand::SecureRandom::fill(&ring::rand::SystemRandom::new(), &mut bytes)
            .map_err(|_| ChallengeError::Unavailable)?;
        let nonce = encode_b64(&bytes);
        let mut inner = self.inner.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        inner.retain(|c| c.expires > now);
        let mine = inner.iter().filter(|c| c.caller == caller).count();
        if mine >= MAX_CHALLENGES_PER_CALLER {
            if let Some(oldest) = inner.iter().position(|c| c.caller == caller) {
                inner.remove(oldest);
            }
        } else if inner.len() >= MAX_CHALLENGES {
            return Err(ChallengeError::TooMany);
        }
        inner.push(Challenge { nonce: nonce.clone(), caller: caller.to_string(), expires: now + CHALLENGE_TTL });
        Ok(nonce)
    }

    /// Remove and return the caller's live nonces that `pick` accepts: the
    /// given nonce, or (without one) every live nonce of the caller. Every
    /// returned nonce is spent whether its signature verifies or not.
    pub fn take(&self, caller: &str, nonce: Option<&str>, now: Instant) -> Vec<String> {
        let mut inner = self.inner.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        inner.retain(|c| c.expires > now);
        let mut taken = Vec::new();
        inner.retain(|c| {
            let hit = c.caller == caller && nonce.is_none_or(|n| n == c.nonce);
            if hit {
                taken.push(c.nonce.clone());
            }
            !hit
        });
        taken
    }

    #[cfg(test)]
    pub fn outstanding(&self) -> usize {
        self.inner.lock().unwrap().len()
    }
}

impl Default for Challenges {
    fn default() -> Self {
        Self::new()
    }
}

// ---------------------------------------------------------------- store

pub fn path_in(dir: &Path) -> PathBuf {
    dir.join("persons-v1.json")
}

/// The persons store (missing = empty). Errors fail closed at writers and
/// soft at listings.
pub fn read(dir: &Path) -> anyhow::Result<State> {
    match std::fs::read(path_in(dir)) {
        Ok(bytes) => {
            let state: State = serde_json::from_slice(&bytes)?;
            state.check()?;
            Ok(state)
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(State::default()),
        Err(error) => Err(error.into()),
    }
}

impl UserStore {
    pub fn persons_path(&self) -> PathBuf {
        path_in(self.dir())
    }

    pub fn persons_snapshot(&self) -> anyhow::Result<State> {
        read(self.dir())
    }

    /// Run `mutate` on the users and persons stores under `users.lock`;
    /// each file is written only when it changed. Entries of revoked tokens
    /// and deleted users are dropped on every persons write.
    pub fn with_persons<T>(
        &self,
        mutate: impl FnOnce(&mut users::State, &mut State) -> Result<T, UserError>,
    ) -> Result<T, UserError> {
        self.with_persons_via(users::VIA_ASSIGNED, mutate)
    }

    /// [`Self::with_persons`]; a token newly bound to owner is a new owner
    /// device reached `via` (see `UserStore::with_via`).
    pub fn with_persons_via<T>(
        &self,
        via: &str,
        mutate: impl FnOnce(&mut users::State, &mut State) -> Result<T, UserError>,
    ) -> Result<T, UserError> {
        let unavailable =
            |e: anyhow::Error| UserError::new(503, "users_unavailable", format!("the persons store is unavailable: {e:#}"));
        let known_tokens: Option<HashSet<String>> =
            self.tokens().list().ok().map(|tokens| tokens.into_iter().map(|t| t.token_id).collect());
        self.with_via(via, |state| {
            let mut persons = read(self.dir()).map_err(unavailable)?;
            let before = persons.clone();
            let result = mutate(state, &mut persons)?;
            persons.users.retain(|user, keys| state.user(user).is_some() && !keys.is_empty());
            persons.drop_removed_owner_person();
            if let Some(known) = &known_tokens {
                persons.token_persons.retain(|token, _| known.contains(token));
                persons.token_claims.retain(|token, _| known.contains(token));
            }
            if persons != before {
                persons.revision = before.revision + 1;
                persons.check().map_err(|e| UserError::new(500, "users_invalid", format!("{e:#}")))?;
                crate::config::atomic::write_private_pretty_json_atomic(&self.persons_path(), &persons, "persons")
                    .map_err(unavailable)?;
            }
            Ok(result)
        })
    }

    /// [`Self::with_persons`] plus an `ownerPersonSet {publicKey, source,
    /// actor}` audit line when `ownerPerson` changed.
    fn with_persons_as<T>(
        &self,
        actor: &str,
        mutate: impl FnOnce(&mut users::State, &mut State) -> Result<T, UserError>,
    ) -> Result<T, UserError> {
        // Only a claim binds a token here: a pending device whose person key
        // the owner holds (`personKey`).
        let (result, changed) = self.with_persons_via(users::VIA_PERSON_KEY, |users_state, persons| {
            let before = persons.owner_person.clone();
            let result = mutate(users_state, persons)?;
            persons.drop_removed_owner_person();
            let changed = (persons.owner_person != before).then(|| persons.owner_person.clone()).flatten();
            Ok((result, changed))
        })?;
        if let Some(person) = changed {
            audit(
                self.dir(),
                "ownerPersonSet",
                json!({ "publicKey": person.public_key, "source": person.source, "actor": actor }),
            );
        }
        Ok(result)
    }

    /// The effective owner person `(publicKey, source)`; `None` = unconfirmed.
    pub fn owner_person(&self) -> Option<(String, String)> {
        self.persons_snapshot().ok().and_then(|persons| effective_owner_person(&persons, self.dir()))
    }

    /// `owner` of `GET /v2/host` (every principal): `{displayName,
    /// fingerprint, confirmed, source}`. `displayName` = the owner's profile
    /// displayName, else the owner user's name; `fingerprint` / `source` are
    /// null while unconfirmed. Best effort (store errors read as unconfirmed).
    pub fn owner_view(&self) -> Value {
        let person = self.owner_person();
        let display_name = crate::management::user_profiles::ProfileStore::at(self.dir())
            .profile(OWNER)
            .display_name
            .or_else(|| self.snapshot().ok().and_then(|state| state.user(OWNER).map(|user| user.name.clone())));
        json!({
            "displayName": display_name,
            "fingerprint": person.as_ref().map(|(key, _)| fingerprint(key)),
            "confirmed": person.is_some(),
            "source": person.map(|(_, source)| source),
        })
    }

    /// Set the owner person locally (`PUT /v2/users/owner-person` from the
    /// root credential on loopback, or the CLI): `public_key` must already be
    /// one of owner's keys (400 `not_an_owner_key`). Source `local`.
    pub fn set_owner_person(&self, public_key: &str, actor: &str) -> Result<(), UserError> {
        let key = normalize_public_key(public_key)
            .ok_or_else(|| UserError::new(400, "invalid_public_key", "publicKey must be base64 / base64url of a 32-byte Ed25519 key"))?;
        self.with_persons_as(actor, |_, persons| {
            if !persons.keys_of(OWNER).iter().any(|k| k.public_key == key) {
                let mut error = UserError::new(400, "not_an_owner_key", "publicKey is not one of the owner's person keys");
                error.details = json!({ "publicKey": key });
                return Err(error);
            }
            let unchanged = persons
                .owner_person
                .as_ref()
                .is_some_and(|p| p.public_key.as_deref() == Some(key.as_str()) && p.source == "local");
            if !unchanged {
                persons.owner_person = Some(OwnerPerson {
                    public_key: Some(key.clone()),
                    set_at: crate::management::instance::now_utc(),
                    source: "local".into(),
                });
            }
            Ok(())
        })
    }

    /// Mark the owner person unconfirmed locally (`DELETE
    /// /v2/users/owner-person`, CLI `clear-person`); no inference afterwards.
    pub fn clear_owner_person(&self, actor: &str) -> Result<(), UserError> {
        self.with_persons_as(actor, |_, persons| {
            if !persons.owner_person.as_ref().is_some_and(|p| p.public_key.is_none()) {
                persons.owner_person = Some(OwnerPerson {
                    public_key: None,
                    set_at: crate::management::instance::now_utc(),
                    source: "local".into(),
                });
            }
            Ok(())
        })
    }

    /// `PUT /v2/users/{id}/person-keys`: replace a user's keys (owner only).
    pub fn set_person_keys(&self, user: &str, keys: Vec<(String, Option<String>)>, actor: &str) -> Result<Vec<PersonKey>, UserError> {
        if keys.len() > MAX_KEYS_PER_USER {
            return Err(UserError::invalid(format!("personKeys: at most {MAX_KEYS_PER_USER} keys")));
        }
        let mut wanted: Vec<(String, Option<String>)> = Vec::new();
        for (key, label) in keys {
            let key = normalize_public_key(&key)
                .ok_or_else(|| UserError::new(400, "invalid_public_key", "publicKey must be base64 / base64url of a 32-byte Ed25519 key"))?;
            let label = match label.map(|l| l.trim().to_string()) {
                Some(l) if l.is_empty() => None,
                Some(l) if l.chars().count() > MAX_LABEL_CHARS || l.chars().any(char::is_control) => {
                    return Err(UserError::invalid(format!("label: at most {MAX_LABEL_CHARS} characters, no control characters")))
                }
                other => other,
            };
            if wanted.iter().any(|(k, _)| *k == key) {
                return Err(UserError::invalid("personKeys: duplicate publicKey"));
            }
            wanted.push((key, label));
        }
        let now = crate::management::instance::now_utc();
        let (keys, added, removed) = self.with_persons_as(actor, |users_state, persons| {
            if users_state.user(user).is_none() {
                return Err(UserError::new(404, "user_not_found", "no user with this id"));
            }
            if user == OWNER {
                persons.settle_owner_person(self.dir());
            }
            for (key, _) in &wanted {
                if let Some(other) = persons.user_of_key(users_state, key).filter(|other| other != user) {
                    let mut error = UserError::new(409, "person_key_in_use", "this key already belongs to another user");
                    error.details = json!({ "publicKey": key, "userId": other });
                    return Err(error);
                }
            }
            let old = persons.users.remove(user).unwrap_or_default();
            // A key of a deleted user may linger until this write; drop it.
            for keys in persons.users.values_mut() {
                keys.retain(|k| !wanted.iter().any(|(w, _)| *w == k.public_key));
            }
            let next: Vec<PersonKey> = wanted
                .iter()
                .map(|(key, label)| PersonKey {
                    public_key: key.clone(),
                    added_at: old.iter().find(|k| k.public_key == *key).map(|k| k.added_at.clone()).unwrap_or_else(|| now.clone()),
                    label: label.clone(),
                })
                .collect();
            let added: Vec<String> = next.iter().filter(|k| !old.iter().any(|o| o.public_key == k.public_key)).map(|k| k.public_key.clone()).collect();
            let removed: Vec<String> = old.iter().filter(|o| !next.iter().any(|k| k.public_key == o.public_key)).map(|o| o.public_key.clone()).collect();
            if !next.is_empty() {
                persons.users.insert(user.to_string(), next.clone());
            }
            Ok((next, added, removed))
        })?;
        audit(self.dir(), "personKeysSet", json!({ "userId": user, "added": added, "removed": removed, "actor": actor }));
        Ok(keys)
    }

    /// Forget a deleted user's keys (best effort).
    pub fn forget_person_user(&self, user: &str) {
        let _ = self.with_persons(|_, persons| {
            persons.users.remove(user);
            Ok(())
        });
    }

    /// The outcome of a verified claim (signature already checked).
    pub fn apply_claim(&self, claim: &VerifiedClaim, actor: &str) -> Result<ClaimResult, UserError> {
        let tokens = self.tokens().list().map_err(|e| UserError::new(503, "client_tokens_unavailable", format!("{e:#}")))?;
        let now = crate::management::instance::now_utc();
        let key = claim.public_key.clone();
        let result = self.with_persons_as(actor, |users_state, persons| {
            let key_user = persons.user_of_key(users_state, &key);
            let Some(token_id) = claim.token_id.as_deref() else {
                // Root credential: the host's owner; the key goes on owner
                // unless another user holds it.
                let outcome = if key_user.is_none() {
                    persons.add_owner_key(&key, "firstRootClaim", self.dir());
                    ClaimOutcome::OwnerKeyAdded
                } else {
                    ClaimOutcome::Recorded
                };
                let person_user = persons.user_of_key(users_state, &key);
                return Ok(ClaimResult { outcome, token_id: None, user_id: Some(OWNER.into()), person_user_id: person_user, previous: None });
            };
            if !tokens.iter().any(|t| t.token_id == token_id) {
                return Err(UserError::new(404, "client_token_not_found", "the calling token no longer exists"));
            }
            let previous = persons.token_persons.insert(token_id.to_string(), key.clone()).filter(|p| *p != key);
            let claim_record = persons.token_claims.entry(token_id.to_string()).or_default();
            claim_record.claimed_at = now.clone();
            if claim.display_name.is_some() {
                claim_record.display_name = claim.display_name.clone();
            }
            if previous.is_some() {
                claim_record.previous_public_key = previous.clone();
            }
            let bound = users_state.user_of_token(token_id).map(|u| u.id.clone());
            let outcome = match (&bound, &key_user) {
                // Pending + known person: the owner approved this person before.
                (None, Some(user)) => {
                    users_state.bindings.insert(token_id.to_string(), user.clone());
                    ClaimOutcome::AutoBound
                }
                (None, None) => ClaimOutcome::Pending,
                // The host's first paired device: its person is the owner.
                (Some(owner), None) if owner == OWNER && tokens.len() == 1 => {
                    persons.add_owner_key(&key, "firstPairing", self.dir());
                    ClaimOutcome::OwnerKeyAdded
                }
                // Already bound: record only, never rebind.
                (Some(_), _) => ClaimOutcome::Recorded,
            };
            let user_id = users_state.user_of_token(token_id).map(|u| u.id.clone());
            let person_user = persons.user_of_key(users_state, &key);
            Ok(ClaimResult { outcome, token_id: Some(token_id.to_string()), user_id, person_user_id: person_user, previous })
        })?;
        let caller = claim.token_id.as_deref().unwrap_or(ROOT_TOKEN_ID);
        if let Some(previous) = &result.previous {
            audit(self.dir(), "tokenPersonChanged", json!({ "tokenId": caller, "previousPublicKey": previous, "publicKey": key }));
        }
        match result.outcome {
            ClaimOutcome::AutoBound => audit(
                self.dir(),
                "tokenAutoBound",
                json!({ "tokenId": caller, "userId": result.user_id, "publicKey": key }),
            ),
            ClaimOutcome::OwnerKeyAdded => audit(
                self.dir(),
                "personKeyAdded",
                json!({ "userId": OWNER, "publicKey": key, "reason": if claim.token_id.is_none() { "rootCredential" } else { "firstPairing" }, "actor": actor }),
            ),
            _ => {}
        }
        audit(
            self.dir(),
            "personClaimed",
            json!({ "tokenId": caller, "publicKey": key, "outcome": result.outcome.as_str(), "userId": result.user_id, "actor": actor }),
        );
        Ok(result)
    }

    /// `DELETE /v2/users/token-persons/{tokenId}/previous` (owner only): the
    /// owner acknowledged that the device now presents another key; clears
    /// `tokenClaims[tokenId].previousPublicKey`. Returns the cleared key
    /// (`None`: nothing was set; idempotent). The device's current key and
    /// its binding are unchanged. 404 `client_token_not_found`.
    pub fn clear_previous_key(&self, token_id: &str, actor: &str) -> Result<Option<String>, UserError> {
        let tokens = self.tokens().list().map_err(|e| UserError::new(503, "client_tokens_unavailable", format!("{e:#}")))?;
        if !tokens.iter().any(|t| t.token_id == token_id) {
            return Err(UserError::new(404, "client_token_not_found", "no client token with this id"));
        }
        let (previous, current) = self.with_persons(|_, persons| {
            let current = persons.token_persons.get(token_id).cloned();
            let previous = persons
                .token_claims
                .get_mut(token_id)
                .and_then(|claim| claim.previous_public_key.take());
            Ok((previous, current))
        })?;
        if let Some(previous) = &previous {
            audit(
                self.dir(),
                "tokenPersonChangeAcknowledged",
                json!({ "tokenId": token_id, "previousPublicKey": previous, "publicKey": current, "actor": actor }),
            );
        }
        Ok(previous)
    }

    /// Record the remote owner's keys of a newly paired peer.
    pub fn record_peer_persons(&self, peer_id: &str, keys: &[String]) {
        if keys.is_empty() {
            return;
        }
        let _ = self.with_persons(|_, persons| {
            persons.peer_persons.insert(peer_id.to_string(), keys.to_vec());
            Ok(())
        });
    }
}

// ---------------------------------------------------------------- owner person

/// The effective owner person `(publicKey, source)`; `None` = unconfirmed.
/// A stored `ownerPerson` decides (its key must still be one of owner's);
/// without one it is inferred ([`infer_owner_person`], source `audit`).
pub fn effective_owner_person(persons: &State, audit_dir: &Path) -> Option<(String, String)> {
    let on_owner = |key: &str| persons.keys_of(OWNER).iter().any(|k| k.public_key == key);
    match &persons.owner_person {
        Some(stored) => stored
            .public_key
            .as_deref()
            .filter(|key| on_owner(key))
            .map(|key| (key.to_string(), stored.source.clone())),
        None => infer_owner_person(persons, audit_dir).map(|key| (key, "audit".to_string())),
    }
}

/// The owner person of a file without `ownerPerson` (no write): the latest
/// `ownerPersonSet` audit entry (the field was written by a build that was
/// later rolled back), else the only owner key, else the earliest owner key
/// added by a root-credential claim, else by the first paired device.
pub fn infer_owner_person(persons: &State, audit_dir: &Path) -> Option<String> {
    let owner_keys = persons.keys_of(OWNER);
    if owner_keys.is_empty() {
        return None;
    }
    let on_owner = |key: &str| owner_keys.iter().any(|k| k.public_key == key);
    let entries = owner_audit_entries(audit_dir);
    if let Some(last) = entries.iter().rev().find(|entry| entry["action"] == "ownerPersonSet") {
        return last["details"]["publicKey"].as_str().filter(|key| on_owner(key)).map(str::to_string);
    }
    if owner_keys.len() == 1 {
        return Some(owner_keys[0].public_key.clone());
    }
    ["rootCredential", "firstPairing"].iter().find_map(|reason| {
        entries
            .iter()
            .filter(|entry| {
                entry["action"] == "personKeyAdded"
                    && entry["details"]["userId"] == OWNER
                    && entry["details"]["reason"] == *reason
            })
            .filter_map(|entry| entry["details"]["publicKey"].as_str())
            .find(|key| on_owner(key))
            .map(str::to_string)
    })
}

/// `personKeyAdded` / `ownerPersonSet` lines of the users audit log, oldest
/// first (missing or unreadable: none).
fn owner_audit_entries(dir: &Path) -> Vec<Value> {
    use std::io::BufRead;
    let Ok(file) = std::fs::File::open(dir.join("audit.jsonl")) else {
        return Vec::new();
    };
    std::io::BufReader::new(file)
        .lines()
        .map_while(Result::ok)
        .filter(|line| line.contains("\"personKeyAdded\"") || line.contains("\"ownerPersonSet\""))
        .filter_map(|line| serde_json::from_str::<Value>(&line).ok())
        .collect()
}

/// An owner key by public key or fingerprint (16 hex digits) — for the CLI.
pub fn resolve_owner_key(persons: &State, selector: &str) -> Option<String> {
    let selector = selector.trim();
    let keys = persons.keys_of(OWNER);
    if let Some(key) = normalize_public_key(selector) {
        return keys.iter().find(|k| k.public_key == key).map(|k| k.public_key.clone());
    }
    let wanted = selector.to_ascii_lowercase();
    keys.iter().find(|k| fingerprint(&k.public_key) == wanted).map(|k| k.public_key.clone())
}

/// A claim whose signature verified.
#[derive(Clone, Debug)]
pub struct VerifiedClaim {
    /// `None` = the root credential.
    pub token_id: Option<String>,
    pub public_key: String,
    pub display_name: Option<String>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ClaimOutcome {
    /// A pending token was bound to the user that holds the key.
    AutoBound,
    /// The key was added to owner (root credential, or the host's first device).
    OwnerKeyAdded,
    /// A pending token with an unknown key: recorded, still pending.
    Pending,
    /// Recorded only (bound token, or a key already known).
    Recorded,
}

impl ClaimOutcome {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::AutoBound => "autoBound",
            Self::OwnerKeyAdded => "ownerKeyAdded",
            Self::Pending => "pending",
            Self::Recorded => "recorded",
        }
    }
}

#[derive(Clone, Debug)]
pub struct ClaimResult {
    pub outcome: ClaimOutcome,
    pub token_id: Option<String>,
    pub user_id: Option<String>,
    pub person_user_id: Option<String>,
    pub previous: Option<String>,
}

// ---------------------------------------------------------------- peers

/// The local owner's person keys, sent to a peer at pairing (best effort).
pub fn local_owner_keys() -> Vec<String> {
    UserStore::open_default()
        .ok()
        .and_then(|store| store.persons_snapshot().ok())
        .map(|state| state.keys_of(OWNER).iter().take(MAX_PEER_KEYS).map(|k| k.public_key.clone()).collect())
        .unwrap_or_default()
}

/// The valid keys of a peer's `ownerPersonKeys` (unknown shapes ignored).
pub fn peer_keys(value: &Value) -> Vec<String> {
    let mut keys: Vec<String> = value
        .get("ownerPersonKeys")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(Value::as_str)
        .filter_map(normalize_public_key)
        .take(MAX_PEER_KEYS)
        .collect();
    keys.dedup();
    keys
}

/// The local user that holds one of a peer's owner keys.
pub fn user_for_peer_keys(keys: &[String]) -> Option<String> {
    let store = UserStore::open_default().ok()?;
    let users_state = store.snapshot().ok()?;
    let persons = store.persons_snapshot().ok()?;
    keys.iter().find_map(|key| persons.user_of_key(&users_state, key))
}

